/**
 * Integration test launcher (@vscode/test-electron). Fixture repos are
 * generated by scripts/build-fixtures.mjs before launch and passed as
 * workspace folders so tests run against REAL git repositories.
 */
import * as path from 'node:path';
import { runTests } from '@vscode/test-electron';

async function main(): Promise<void> {
  const fixturesDir = process.env.JETGIT_FIXTURES_DIR;
  if (!fixturesDir) {
    throw new Error('JETGIT_FIXTURES_DIR must point at the generated fixture repos');
  }
  const extensionDevelopmentPath = path.resolve(__dirname, '..', '..');
  const repoA = path.join(fixturesDir, 'repo-a');
  const repoAWorktree = path.join(fixturesDir, 'repo-a-wt');
  const repoB = path.join(fixturesDir, 'repo-b');

  await runTests({
    extensionDevelopmentPath,
    extensionTestsPath: path.resolve(__dirname, './suite/index'),
    launchArgs: [repoA, repoAWorktree, repoB, '--disable-extensions', '--disable-gpu'],
  });
}

function fail(err: unknown): never {
  console.error('Integration tests failed', err);
  process.exit(1);
}

main().catch(fail);
